use ark_ff::{BigInteger,One,PrimeField,Zero};
use kimchi::{circuits::{gate::{CircuitGate,GateType},wires::{Wire,COLUMNS}},proof::ProverProof,prover_index::testing::new_index_for_test_with_lookups_and_custom_srs,verifier::verify};
use mina_curves::pasta::{Fp,Vesta,VestaParameters};
use mina_poseidon::{constants::PlonkSpongeConstantsKimchi,pasta::FULL_ROUNDS,sponge::{DefaultFqSponge,DefaultFrSponge}};
use poly_commitment::{commitment::CommitmentCurve,ipa::{OpeningProof,SRS},SRS as SrsTrait};
use groupmap::GroupMap;
use std::time::Instant;
include!("../../cases.rs");
type Base=DefaultFqSponge<VestaParameters,PlonkSpongeConstantsKimchi,FULL_ROUNDS>;
type Scalar=DefaultFrSponge<Fp,PlonkSpongeConstantsKimchi,FULL_ROUNDS>;
type Proof=ProverProof<Vesta,OpeningProof<Vesta,FULL_ROUNDS>,FULL_ROUNDS>;
struct Build{values:Vec<Fp>,rows:Vec<([usize;3],[Fp;5])>}
impl Build{
 fn var(&mut self,v:Fp)->usize{self.values.push(v);self.values.len()-1}
 fn gate(&mut self,ids:[usize;3],c:[Fp;5]){self.rows.push((ids,c));}
 fn linear(&mut self,x:usize,y:usize,cx:Fp,cy:Fp,c:Fp)->usize{let z=self.var(cx*self.values[x]+cy*self.values[y]+c);self.gate([x,y,z],[cx,cy,-Fp::one(),Fp::zero(),c]);z}
 fn mul(&mut self,x:usize,y:usize)->usize{let z=self.var(self.values[x]*self.values[y]);self.gate([x,y,z],[Fp::zero(),Fp::zero(),-Fp::one(),Fp::one(),Fp::zero()]);z}
 fn equal(&mut self,x:usize,y:usize){self.gate([x,y,0],[Fp::one(),-Fp::one(),Fp::zero(),Fp::zero(),Fp::zero()]);}
 fn range(&mut self,x:usize,n:usize){let bits=self.values[x].into_bigint();let mut acc=0;for i in (0..n).rev(){let bit=self.var(Fp::from(bits.get_bit(i) as u64));self.gate([bit,bit,0],[-Fp::one(),Fp::zero(),Fp::zero(),Fp::one(),Fp::zero()]);acc=self.linear(acc,bit,Fp::from(2u64),Fp::one(),Fp::zero());}self.equal(x,acc);}
 fn finish(self)->(Vec<CircuitGate<Fp>>,[Vec<Fp>;COLUMNS]){let mut gates:Vec<_>=self.rows.iter().enumerate().map(|(r,(_,coeff))|{let mut cs=coeff.to_vec();cs.resize(10,Fp::zero());CircuitGate::new(GateType::Generic,Wire::for_row(r),cs)}).collect();let mut witness=std::array::from_fn(|_|vec![Fp::zero();gates.len()]);let mut occurrences=vec![Vec::<Wire>::new();self.values.len()];for(r,(ids,_))in self.rows.iter().enumerate(){for c in 0..3{witness[c][r]=self.values[ids[c]];occurrences[ids[c]].push(Wire::new(r,c));}}for cells in occurrences{for i in 0..cells.len(){let w=cells[i];gates[w.row].wires[w.col]=cells[(i+1)%cells.len()];}}(gates,witness)}
}
fn circuit(input:[u64;6])->(Vec<CircuitGate<Fp>>,[Vec<Fp>;COLUMNS]){let z=Fp::zero();let o=Fp::one();let mut b=Build{values:vec![z],rows:vec![]};let d=b.var(Fp::from(input[4]));let r=b.var(Fp::from(input[5]));for x in [d,r]{b.gate([x,0,0],[o,z,z,z,z]);}b.gate([0,0,0],[o,z,z,z,z]);let a:[usize;4]=std::array::from_fn(|i|b.var(Fp::from(input[i])));for x in a{b.range(x,16);}b.range(d,33);b.range(r,17);let dx=b.linear(a[0],a[2],o,-o,z);let dy=b.linear(a[1],a[3],o,-o,z);let dx2=b.mul(dx,dx);let dy2=b.mul(dy,dy);let sum=b.linear(dx2,dy2,o,o,z);b.equal(sum,d);let rs=b.mul(r,r);let low=b.linear(d,rs,o,-o,z);b.range(low,18);let rp=b.linear(r,0,o,z,o);let rps=b.mul(rp,rp);let high=b.linear(rps,d,o,-o,-o);b.range(high,18);b.finish()}
fn main()->anyhow::Result<()>{println!("{}",serde_json::json!({"phase":"start","framework":"Kimchi Vesta IPA","os":std::env::consts::OS,"arch":std::env::consts::ARCH}));let t=Instant::now();let(gates,_)=circuit(CASES[0]);let index=new_index_for_test_with_lookups_and_custom_srs::<FULL_ROUNDS,Vesta,SRS<Vesta>,_>(gates,2,0,vec![],None,false,None,|domain,size|{let srs=SRS::<Vesta>::create(size);srs.get_lagrange_basis(domain);srs},false);let verifier=index.verifier_index();let map=<Vesta as CommitmentCurve>::Map::setup();println!("{}",serde_json::json!({"phase":"keys","setup_ms":t.elapsed().as_secs_f64()*1000.,"public":2,"srs":"transparent local RAM-only IPA","max_poly_size":index.max_poly_size}));
 for(i,a)in CASES.iter().enumerate(){let t=Instant::now();let(_,witness)=circuit(*a);let wms=t.elapsed().as_secs_f64()*1000.;let t=Instant::now();let proof=Proof::create_recursive::<Base,Scalar,_>(&map,witness,&[],&index,vec![],None,&mut rand::rngs::OsRng)?;let pms=t.elapsed().as_secs_f64()*1000.;let public=[Fp::from(a[4]),Fp::from(a[5])];let t=Instant::now();verify::<FULL_ROUNDS,Vesta,Base,Scalar,OpeningProof<Vesta,FULL_ROUNDS>>(&map,&verifier,&proof,&public)?;let vms=t.elapsed().as_secs_f64()*1000.;for j in 0..2{let mut fake=public;fake[j]+=Fp::one();assert!(verify::<FULL_ROUNDS,Vesta,Base,Scalar,OpeningProof<Vesta,FULL_ROUNDS>>(&map,&verifier,&proof,&fake).is_err());}let bytes=rmp_serde::to_vec(&proof)?;let mut fake=proof.clone();fake.evals.w[0].zeta[0]+=Fp::one();assert!(verify::<FULL_ROUNDS,Vesta,Base,Scalar,OpeningProof<Vesta,FULL_ROUNDS>>(&map,&verifier,&fake,&public).is_err());println!("{}",serde_json::json!({"phase":"sample","case_id":i,"verified":true,"witness_ms":wms,"prove_ms":pms,"verify_ms":vms,"proof_bytes":bytes.len(),"size_format":"rmp-serde","changed_public_rejected":true,"changed_root_rejected":true,"tampered_proof_rejected":true}));}
 for a in BAD{let(_,w)=circuit(a);assert!(index.verify(&w,&[Fp::from(a[4]),Fp::from(a[5])]).is_err());}
 println!("{}",serde_json::json!({"phase":"summary","samples":7,"invalid_cases_rejected":6,"all_verified":true,"proofs_saved":false}));Ok(())}
